.r23-scene .part{min-width:0;min-height:0;display:flex;flex-direction:column;text-align:left;border:1px solid rgba(127,185,208,.15);border-radius:18px;padding:18px;position:relative;background:radial-gradient(ellipse at 50% 54%,rgba(85,178,174,.075),transparent 70%);box-shadow:inset 0 1px 0 rgba(217,245,248,.06)}
.r23-scene .part[aria-pressed=true]{border-color:var(--tone);box-shadow:inset 0 1px 0 rgba(217,245,248,.15),0 0 26px color-mix(in srgb,var(--tone) 5%,transparent)}
.r23-scene .part.CPU{grid-row:1/3}
.r23-scene .part-head{display:flex;justify-content:space-between;align-items:center;gap:10px}
.r23-scene .part-head h3{font:26px var(--font-number);color:var(--secondary)}
.r23-scene .part .sub{font-size:13px;color:var(--muted);margin-top:4px}
.r23-scene .art svg{display:block;width:100%;max-height:100%;overflow:visible}
.r23-scene .CPU .art svg{max-height:390px}
.r23-scene .MEM .art svg,.r23-scene .IO .art svg{max-height:177px}
.r23-scene .part-value{display:flex;align-items:baseline;justify-content:space-between;gap:12px;border-top:1px solid var(--border);padding-top:11px;font-size:13px;color:var(--muted)}
.r23-scene .part-value b{font:29px var(--font-number);color:var(--tone);font-weight:450}
.r23-scene .part-value b small{font-size:15px}
.r23-scene .part{transition:border-color 180ms,box-shadow 180ms}
.r23-scene .work-active{opacity:1;transition:opacity 450ms ease}
.r23-scene .work-animated{animation-duration:var(--work-duration,3.2s);animation-timing-function:linear;animation-iteration-count:infinite;animation-delay:calc(var(--epoch-offset,0s) + var(--work-phase,0s));transform-box:view-box;transform-origin:0 0}
.r23-scene .part.U .art>svg{filter:grayscale(1) brightness(.72)}
.r23-scene .part.U .work-active{opacity:.12}
.r23-scene .part.U .work-animated,.r23-scene [data-motion="paused"] .work-animated{animation-play-state:paused}
@media(prefers-reduced-motion:reduce){.r23-scene .work-animated{animation:none!important;transform:translate(var(--static-x),var(--static-y))!important;opacity:var(--static-opacity)!important}
.r23-scene .work-active,.r23-scene .part{transition:none!important}}
