/* Local h-domain workbench; no dashboard-wide selectors. */
.diagnostic-screen[data-domain="h"].r23-screen .diagnostic-main{grid-template-rows:48px 20px minmax(0,1fr) 160px;padding:16px;gap:8px}
.r23-scene{position:relative;min-height:0;display:grid;grid-template-columns:1.05fr 1fr;grid-template-rows:minmax(0,1fr) minmax(0,1fr) 24px;gap:14px;overflow:hidden;--epoch-offset:0s}
.r23-scene .part{display:flex;flex-direction:column;align-items:stretch;min-width:0;min-height:0;overflow:hidden;position:relative;border:1px solid #294853;border-radius:16px;background:linear-gradient(145deg,#0b202d,#091725);color:var(--state);padding:16px;text-align:left;cursor:pointer;font:inherit}
.r23-scene .part.CPU{grid-row:span 2}.r23-scene .part[aria-pressed="true"]{border-color:var(--state);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--state) 16%,transparent)}
.r23-scene .part-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-shrink:0}.r23-scene .part-head strong{font-size:24px;color:var(--text);font-weight:500}.r23-scene .part-head small{font-size:14px;color:var(--muted);display:block;margin-top:4px}.r23-scene .r23-status{font-size:17px;white-space:nowrap}
.r23-scene .art{position:relative;display:flex;align-items:center;justify-content:center;flex:1;min-height:0;overflow:visible;pointer-events:none}.r23-scene .art>svg{display:block;width:100%;height:100%;max-height:100%;overflow:visible;color:var(--state)}
.r23-scene .part-value{position:relative;display:flex;justify-content:space-between;align-items:center;gap:8px;padding-top:8px;border-top:1px solid #29414d;flex-shrink:0}.r23-scene .part-value span{font-size:14px;color:var(--muted)}.r23-scene .part-value b{font-size:22px;font-weight:500}
.r23-scene .r23-caption{grid-column:1/-1;margin:0;font-size:13px;color:var(--muted);align-self:end}.r23-scene .part.U .work-animated{opacity:0!important}
@media(max-width:1000px){.diagnostic-screen[data-domain="h"].r23-screen .diagnostic-main{display:flex;flex-direction:column;overflow:visible}.r23-scene{min-height:850px;grid-template-columns:1fr;grid-template-rows:340px 235px 235px auto}.r23-scene .part.CPU{grid-row:auto}.r23-scene .part-head strong{font-size:20px}.r23-scene .r23-status{font-size:14px}.r23-scene .part-value b{font-size:18px}.r23-scene .r23-caption{font-size:12px}}

/* 03 monitoring stays visible for the selected registered host. */
.diagnostic-screen[data-domain="h"].r23-screen .diagnostic-main{grid-template-rows:48px 20px minmax(0,1fr)}.r23-screen .diagnostic-sidebar{overflow-y:auto}.r23-monitor{border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:14px}.r23-monitor>h2{font-size:21px;margin-bottom:12px}.r23-metric-list{display:grid;gap:7px}.r23-metric-list button{display:flex;justify-content:space-between;text-align:left;gap:8px;font-size:13px}.r23-metric-list [aria-pressed="true"]{background:rgba(127,185,235,.12)}.r23-monitor .diag-trend-panel{padding:12px 0 0;border:0;background:none}.r23-monitor .diag-trend-panel header{flex-wrap:wrap;gap:8px}.r23-monitor .diag-trend-panel h3{font-size:16px}.r23-monitor .diagnostic-plot{height:145px}.r23-monitor .diag-trend-panel p{font-size:11px;line-height:1.7}.r23-screen .diag-queue{max-height:205px;overflow-y:auto;flex:none}.r23-screen .diagnostic-sidebar>header{flex-shrink:0}
